messages.content:
Berikut manifest game "Petualangan Sang Pemakan" — Endless Runner edukasi bergaya Cartoon dengan tempo Santai. Saya menambahkan burung pelatuk sebagai item karnivora untuk menguji miskonsepsi "semua pemakan daging itu buas".

```js
AISYS.defineGame({
  schema: 1, kit: "endless-runner",
  id: "petualangan-sang-pemakan", title: "Petualangan Sang Pemakan", seed: "pemakan-01",
  theme: { preset: "cartoon" },

  learning: {
    subject: "Ilmu Pengetahuan Alam",
    concept: "Penggolongan hewan berdasarkan jenis makanannya: herbivora, karnivora, omnivora",
    objectives: ["Mengelompokkan hewan ke dalam herbivora, karnivora, dan omnivora berdasarkan jenis makanannya"],
    misconceptions: ["Semua hewan pemakan daging itu buas dan berbahaya"],
    mode: "category",
    categories: [
      { id: "herbivora", label: "Herbivora", color: "#3FA34D" },
      { id: "karnivora", label: "Karnivora", color: "#E5484D" },
      { id: "omnivora",  label: "Omnivora",  color: "#F2A93B" }
    ],
    items: [
      { id: "sapi",      label: "Sapi",       category: "herbivora", explain: "Memakan rumput dan tumbuhan, jadi herbivora." },
      { id: "kambing",   label: "Kambing",    category: "herbivora", explain: "Pemakan daun dan rumput, termasuk herbivora." },
      { id: "kelinci",   label: "Kelinci",    category: "herbivora", explain: "Memakan sayur dan rumput, jadi herbivora." },
      { id: "gajah",     label: "Gajah",      category: "herbivora", explain: "Memakan daun, buah, dan rumput, jadi herbivora." },
      { id: "singa",     label: "Singa",      category: "karnivora", explain: "Pemakan daging, jadi karnivora." },
      { id: "harimau",   label: "Harimau",    category: "karnivora", explain: "Berburu dan memakan daging, jadi karnivora." },
      { id: "elang",     label: "Elang",      category: "karnivora", explain: "Memakan daging hasil buruan, jadi karnivora." },
      { id: "pelatuk",   label: "Burung pelatuk", category: "karnivora", explain: "Pemakan serangga; karnivora tak selalu buas dan berbahaya." },
      { id: "ayam",      label: "Ayam",       category: "omnivora",  explain: "Makan biji, serangga, dan cacing, jadi omnivora." },
      { id: "babi",      label: "Babi",       category: "omnivora",  explain: "Makan tumbuhan dan hewan kecil, jadi omnivora." },
      { id: "beruang",   label: "Beruang",    category: "omnivora",  explain: "Makan buah, madu, ikan, dan tumbuhan, jadi omnivora." },
      { id: "monyet",    label: "Monyet",     category: "omnivora",  explain: "Makan buah, daun, dan serangga, jadi omnivora." }
    ],
    target: { rotateAfterCorrect: 5, bias: 0.5 }
  },

  player: { x: 220, w: 44, h: 56, gravity: 2400, jumpVelocity: 900, lives: 5, invulnerableSec: 1.2 },
  world:  { groundY: 600, speed: 300, maxSpeed: 600, accel: 4 },

  spawner: {
    interval: [0.9, 1.5],
    table: [
      { type: "hazard", id: "batu",  w: 44, h: 48, weight: 3 },
      { type: "hazard", id: "semak", w: 90, h: 40, weight: 2 },
      { type: "item", weight: 5, heights: ["ground", "mid", "high"] }
    ]
  },

  rules: {
    perSecond: 5,
    correct: { score: 50, sfx: "coin" },
    wrong:   { score: -20, sfx: "hit", showExplain: true },
    hazard:  { lives: -1, sfx: "hit", shake: 8 },
    combo:   { step: 5, max: 4 },
    difficulty: { everySec: 20, speed: 20 }
  }
});
// END_OF_MANIFEST
```

Game ini mengajak pemain mengambil hewan yang cocok dengan target kategori (Herbivora/Karnivora/Omnivora) sambil melompati batu dan semak. Asumsi penting: burung pelatuk dipakai sebagai item karnivora untuk meluruskan miskonsepsi bahwa semua pemakan daging itu buas.
